import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"サービス状態","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. サービス状態とコントロール","slug":"_1-サービス状態とコントロール","link":"#_1-サービス状態とコントロール","children":[]},{"level":2,"title":"2. 3 プロセス統合リアルタイムログビューアー","slug":"_2-3-プロセス統合リアルタイムログビューアー","link":"#_2-3-プロセス統合リアルタイムログビューアー","children":[{"level":3,"title":"絞り込みとログ消去","slug":"絞り込みとログ消去","link":"#絞り込みとログ消去","children":[]}]}],"relativePath":"ja-JP/user-guide/settings/service-status.md","filePath":"ja-JP/user-guide/settings/service-status.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/settings/service-status.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="サービス状態" tabindex="-1">サービス状態 <a class="header-anchor" href="#サービス状態" aria-label="Permalink to “サービス状態”">​</a></h1><p>サービス状態画面では、Lertaro のバックグラウンドインデックスサービスの稼働状況を一元監視し、Service、App、Hook の 3 大プロセスのリアルタイムログを閲覧できます。設定画面は <strong>設定 → サービス状態</strong> です。</p><h2 id="_1-サービス状態とコントロール" tabindex="-1">1. サービス状態とコントロール <a class="header-anchor" href="#_1-サービス状態とコントロール" aria-label="Permalink to “1. サービス状態とコントロール”">​</a></h2><p>上部のステータスカードには、バックグラウンドインデックスサービスの稼働状況がリアルタイムに表示されます。</p><ul><li><strong>状態表示</strong>： <ul><li><strong>準備完了（Ready）</strong>：サービスが正常稼働しており、インデックス済みのファイルおよびフォルダーの総数が表示されます。</li><li><strong>インデックス作成中（Indexing）</strong>：初期構築または増分スキャンの実行中（スピナーが表示されます）。</li><li><strong>インストール中（Installing）</strong>：Windows サービスの登録および起動処理中。</li><li><strong>エラー（Error）</strong>：サービスが停止中または異常終了している状態（エラー内容と警告マークを表示）。</li></ul></li><li><strong>サービスの自己修復とインストール</strong>：サービスが未インストールまたはエラーの場合にのみ <strong>サービスをインストールして起動</strong> ボタンが表示されます。正常稼働時は意図しない中断を防ぐため常時バックグラウンドで稼働し続けます。</li></ul><h2 id="_2-3-プロセス統合リアルタイムログビューアー" tabindex="-1">2. 3 プロセス統合リアルタイムログビューアー <a class="header-anchor" href="#_2-3-プロセス統合リアルタイムログビューアー" aria-label="Permalink to “2. 3 プロセス統合リアルタイムログビューアー”">​</a></h2><p>下部のログビューアーは、Lertaro を構成する 3 つのプロセスに対応するタブに分かれています。</p><ul><li><strong>App タブ</strong>：フロントエンド WPF UI、検索インタラクション、ホットキー応答、描画に関するログ。</li><li><strong>Hook タブ</strong>：低レベルキーボードフックプロセス（<code>Lertaro.Service.exe --hook</code>）のキー監視と隔離状態に関するログ。</li><li><strong>Service タブ</strong>：管理者権限バックグラウンドサービス（<code>Lertaro.Service.exe</code>）の USN ジャーナル解析、ディスクスキャン、インメモリツリー構築、IPC 通信ログ。</li></ul><h3 id="絞り込みとログ消去" tabindex="-1">絞り込みとログ消去 <a class="header-anchor" href="#絞り込みとログ消去" aria-label="Permalink to “絞り込みとログ消去”">​</a></h3><ul><li><strong>ログレベルフィルター</strong>：「すべて / エラー / 警告 / 情報 / デバッグ」から選択でき、重大度に応じて色分け表示されます。</li><li><strong>リアルタイム検索</strong>：キーワードを入力してログ行を絞り込み可能。</li><li><strong>ログの安全な消去</strong>：<strong>ログを消去</strong> をクリックすると表示中のタブのログを消去します。Service タブのログは IPC 経由で安全に切り詰められます。</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};